const input = $input.first().json;
const message = input.chatInput || '';
const msgLower = message.toLowerCase().trim();
const words = message.trim().split(/\s+/);

// Mots-clés analytiques → force Sonnet même sur message court
const analyticKeywords = [
  'pourquoi', 'analyse', 'analysе', 'impact', 'compare', 'comparе',
  'explique', 'comment', 'quelles sont', 'quels sont', 'tendance',
  'perspective', 'risque', 'opportunité', 'stratégie', 'implications',
  'conséquences', 'difference', 'différence', 'versus', ' vs '
];
const isAnalytic = analyticKeywords.some(k => msgLower.includes(k));

// Mots-clés liste rapide → force Haiku même sur message long
const listKeywords = [
  'donne-moi les news', 'dernières news', 'derniers articles',
  'quoi de neuf', "qu'est ce qu'il s'est passé", 'actu', 
  'résumé', 'liste', 'recap', 'récap'
];
const isList = listKeywords.some(k => msgLower.includes(k));

// Salutations/questions triviales → Haiku
const isTrivial = 
  words.length <= 3 ||
  /^(salut|bonjour|merci|ok|oui|non|hello|hi|coucou|aide|help)$/i.test(msgLower);

// Logique de décision
let model;
if (isAnalytic) {
  model = 'claude-sonnet-4-20250514'; // Analytique → Sonnet quelle que soit la longueur
} else if (isTrivial || isList) {
  model = 'claude-haiku-4-5-20251001'; // Trivial ou liste → Haiku
} else {
  // Par défaut : longueur du message comme tiebreaker
  model = words.length > 8 ? 'claude-sonnet-4-20250514' : 'claude-haiku-4-5-20251001';
}

console.log(`Message: "${message}" → ${isAnalytic ? 'ANALYTIQUE' : isList ? 'LISTE' : isTrivial ? 'TRIVIAL' : 'DEFAULT'} → ${model}`);

return {
  json: {
    message,
    model
  }
};

const response = $input.first().json;

// Si erreur upstream (Supabase ou Claude)
if (response.error || !response.content) {
  console.log('Erreur upstream:', JSON.stringify(response).substring(0, 200));
  return {
    json: {
      output: 'Désolé, une erreur est survenue. Réessaie dans quelques instants.'
    }
  };
}

const text = response.content?.[0]?.text || 'Désolé, je n\'ai pas pu générer de réponse.';
const model = response.model || '';
const tokens = response.usage ? 
  `${response.usage.input_tokens}in / ${response.usage.output_tokens}out` : '';

console.log(`Modèle: ${model} | Tokens: ${tokens}`);

return {
  json: {
    output: text
  }
};

const inputMessage = $('Sélecteur Modèle').first().json.message;
const model = $('Sélecteur Modèle').first().json.model;
const msgLower = inputMessage.toLowerCase();

// Secteurs détectables dans le message
const secteurMap = {
  'ia': 'IA', 'intelligence artificielle': 'IA',
  'crypto': 'Crypto', 'bitcoin': 'Crypto', 'btc': 'Crypto', 'eth': 'Crypto',
  'finance': 'Finance', 'marché': 'Finance', 'bourse': 'Finance',
  'tech': 'Tech', 'technologie': 'Tech',
  'cyber': 'Cybersécurité', 'sécurité': 'Cybersécurité', 'hack': 'Cybersécurité',
  'énergie': 'Énergie', 'energie': 'Énergie', 'solaire': 'Énergie',
  'santé': 'Santé', 'sante': 'Santé', 'pharma': 'Santé'
};

// Tickers détectables dans le message
const allTickers = $input.all().flatMap(i => 
  (i.json.tickers || '').split(',').map(t => t.trim().toUpperCase()).filter(t => t)
);
const uniqueTickers = [...new Set(allTickers)];
const mentionedTicker = uniqueTickers.find(t => msgLower.includes(t.toLowerCase()));

// Secteur mentionné
const mentionedSecteur = Object.entries(secteurMap)
  .find(([key]) => msgLower.includes(key))?.[1];

// Filtrage
let articles = $input.all();

if (mentionedTicker) {
  const filtered = articles.filter(i => 
    (i.json.tickers || '').toUpperCase().includes(mentionedTicker)
  );
  if (filtered.length > 0) articles = filtered;
} else if (mentionedSecteur) {
  const filtered = articles.filter(i => i.json.sector === mentionedSecteur);
  if (filtered.length > 0) articles = filtered;
}

// Extraction résumé depuis le JSON analysis
function sanitizeResume(text) {
  if (!text || typeof text !== 'string') return '';
  return text
    // Strip les tentatives de changement de rôle
    .replace(/ignore\s+(les\s+)?instructions?\s+(précédentes?|ci-dessus|above|previous)/gi, '[...]')
    .replace(/tu\s+es\s+maintenant/gi, '[...]')
    .replace(/you\s+are\s+now/gi, '[...]')
    .replace(/act\s+as/gi, '[...]')
    // Strip les faux délimiteurs de prompt
    .replace(/\\n(Human|Assistant|System|User)\s*:/gi, ' ')
    .replace(/\n(Human|Assistant|System|User)\s*:/gi, ' ')
    .replace(/#{1,6}\s*(system|instruction|prompt)/gi, '[...]')
    // Strip les balises HTML/XML résiduelles
    .replace(/<[^>]{0,100}>/g, '')
    // Normalise les sauts de ligne multiples
    .replace(/\n{3,}/g, '\n\n')
    // Tronque
    .substring(0, 425)
    .trim();
}

function extractResume(analysis) {
  if (!analysis) return '';
  try {
    const parsed = JSON.parse(analysis);
    return sanitizeResume(parsed.resume || '');
  } catch {
    return sanitizeResume(analysis.substring(0, 425));
  }
}

const mapped = articles.map(i => ({
  titre: i.json.title,
  secteur: i.json.sector,
  importance: i.json.importance,
  sentiment: i.json.sentiment,
  tickers: i.json.tickers,
  date: i.json.published_at,
  resume: extractResume(i.json.analysis)
}));

const promptStyle = model === 'claude-sonnet-4-20250514'
  ? `Analyse détaillée en 5-8 phrases. Structure ta réponse avec des points clés si pertinent. Cite les titres sources et explique les implications.`
  : `Réponse courte et directe en 2-3 phrases max. Va à l'essentiel, cite juste les titres.`;

return {
  json: {
    articles: mapped,
    message: inputMessage,
    model,
    promptStyle,  // ← nouveau
    filtre: mentionedTicker || mentionedSecteur || 'aucun'
  }
};
